export const events = {
	appFailed: (callback: (payload: Failure) => void) => listen<Failure>("app.failed", callback),
	libraryAnalysed: (callback: (payload: string) => void) => listen<string>("library.analysed", callback),
	libraryChanged: (callback: (payload: LibraryChange) => void) => listen<LibraryChange>("library.changed", callback),
	libraryScanning: (callback: (payload: Scanning) => void) => listen<Scanning>("library.scanning", callback),
	playerPosition: (callback: (payload: Position) => void) => listen<Position>("player.position", callback),
	playerState: (callback: (payload: PlayerState) => void) => listen<PlayerState>("player.state", callback),
	playerVisual: (callback: (payload: Uint8Array) => void) => listen<Uint8Array>("player.visual", callback),
	playlistsChanged: (callback: (payload: null) => void) => listen<null>("playlists.changed", callback),
	soundDevices: (callback: (payload: DeviceInfo[]) => void) => listen<DeviceInfo[]>("sound.devices", callback),
};

export type AlbumSettings = {
	transitions: boolean,
};

/**  Where a queued song came from, which decides how it meets its neighbours. */
export type Context = { type: "songs" } | { type: "album"; key: string } | { type: "playlist"; id: number } | { type: "queue" };

export type CoverWrites = "ask" | "files" | "attacca";

export type Cut = {
	hz: number,
	slope: number,
};

export type DeviceInfo = {
	name: string,
	description: string,
};

/**  A song's own settings. None of them changes the file. */
export type Edits = {
	start: number | null,
	end: number | null,
	/**  Decibels on top of volume matching. */
	volume: number,
	equalizer: Equalizer | null,
	filters: Filters | null,
	transition: Transition | null,
};

/**  A playlist entry: a song in the library, or one shared with you that isn't here yet. */
export type Entry = {
	id: number,
	song: string | null,
	missing: Missing | null,
};

export type Equalizer = {
	preamp: number,
	gains: number[],
};

export type Failure = {
	message: string,
};

export type Filters = {
	highpass: Cut | null,
	lowpass: Cut | null,
};

export type ImportPreview = {
	name: string,
	songs: number,
	found: number,
	missing: number,
	/**  Songs you already edited that the sender edited too. */
	bothEdited: number,
};

export type LibraryChange = {
	changed: string[],
	removed: string[],
};

export type Listening = {
	loudness: number,
	peak: number,
	rhythm: Rhythm | null,
	suggestedStart: number,
	suggestedEnd: number,
};

export type Missing = {
	title: string,
	artist: string | null,
	album: string | null,
	duration: number,
};

/**  What a song is called: the title in its tags, or its file's name. */
export type Names = "tags" | "files";

export type Pair = {
	from: string,
	to: string,
	transition: Transition,
};

export type PlayerState = {
	playing: boolean,
	index: number | null,
	queue: QueueEntry[],
	volume: number,
	upcoming: Upcoming | null,
	start: number,
	end: number | null,
};

export type Playlist = {
	id: number,
	name: string,
	cover: string | null,
	transition: Transition | null,
	entries: Entry[],
	pairs: Pair[],
};

export type PlaylistSummary = {
	id: number,
	name: string,
	cover: string | null,
	count: number,
	covers: string[],
};

export type Position = {
	token: number,
	seconds: number,
	playing: boolean,
	crossing: number | null,
};

export type Preset = {
	name: string,
	equalizer: Equalizer,
};

export type QueueEntry = {
	token: number,
	song: string,
	context: Context,
};

export type Rhythm = {
	tempo: number,
	beats: number[],
	downbeat: number,
};

export type Scanning = {
	busy: boolean,
};

export type Song = {
	id: string,
	title: string | null,
	artist: string | null,
	album: string | null,
	albumArtist: string | null,
	track: number | null,
	disc: number | null,
	year: number | null,
	genre: string | null,
	duration: number,
	/**  File name without its extension, shown when the song has no title. */
	name: string,
	/**  Name of the folder holding the file, shown when the song has no album. */
	folder: string,
	/**  Where the song's file is. */
	path: string,
	cover: string | null,
	added: number,
	tempo: number | null,
	analysed: boolean,
	edited: boolean,
	/**  The song's own Transition out, when it has one. */
	transition: Transition | null,
};

export type SongDetail = {
	song: Song,
	edits: Edits,
	listening: Listening | null,
	path: string | null,
};

/**  How everything sounds, unless a song says otherwise. */
export type SoundSettings = {
	equalizer: Equalizer,
	filters: Filters,
	matching: boolean,
	presets: Preset[],
	output: string | null,
	volume: number,
	coverWrites: CoverWrites,
	names: Names,
};

export type SoundState = {
	settings: SoundSettings,
	devices: DeviceInfo[],
};

export type Transition = {
	kind: TransitionName,
	seconds: number,
	snap: boolean,
};

export type TransitionName = "none" | "fade" | "rise" | "blend" | "wave" | "melt" | "slam";

/**
 *  What the person is trying out between two songs before it's saved: where the first ends,
 *  where the second starts and the transition between them.
 */
export type Trial = {
	end?: number | null,
	start?: number | null,
	transition?: Transition | null,
};

/**  The transition into the next song, placed on the playing song's timeline. */
export type Upcoming = {
	kind: TransitionName,
	cue: number,
	overlap: number,
	start: number,
};
